// Разбор текста выписки Kaspi Gold (нода Extract From File → $json.text).
// Не зависим от переносов строк: склеиваем всё в одну строку и режем по «ДД.ММ.ГГ ± сумма ₸ Операция».
// Сверка: сумма разобранных покупок должна совпасть со строкой «Покупки» из сводки выписки.
const raw = String($json.text || '');
const fail = (reason) => [{ json: { ok: false, reason, ops: [] } }];
if (!/Kaspi/i.test(raw) || !/ВЫПИСКА/i.test(raw)) return fail('это не похоже на выписку Kaspi Gold');

const t = raw.replace(/[   ]/g, ' ').replace(/[^\S ]+/g, ' ').replace(/ {2,}/g, ' ');
const money = (s) => Number(String(s).replace(/ /g, '').replace(',', '.'));
const AMT = '([+-]) ?(\\d{1,3}(?: \\d{3})*,\\d{2}) ?(?:₸|Т|T)';
const OPS = 'Покупка|Перевод|Пополнение|Снятие|Платеж|Платёж|Погашение|Разное';
const KIND = { 'Покупка': 'purchase', 'Перевод': 'transfer', 'Пополнение': 'topup', 'Снятие': 'withdrawal' };

const period = /за период с (\d{2})\.(\d{2})\.(\d{2}) по (\d{2})\.(\d{2})\.(\d{2})/.exec(t);
const summary = new RegExp('Покупки ' + AMT).exec(t);   // «Покупки - 27 856,76 ₸»
// Карта: у двух пользователей разные карты → одинаковые траты не должны склеиваться дедупом.
const cardM = /Номер карты: ?\*?(\d{4})/.exec(t);
const card = cardM ? cardM[1] : '';
// Подпись карты: имя того, кто прислал выписку (owners в ноде Config: 'id:Имя,id:Имя').
const owners = Object.fromEntries(String($('Config').first().json.owners || '').split(',')
  .map((s) => s.split(':').map((x) => x.trim())).filter((p) => p.length === 2));
const fromId = String($('Telegram Trigger').first().json.message?.from?.id || '');
const cardLabel = owners[fromId] || 'Карта';
const iso = (d, m, y) => `20${y}-${m}-${d}`;

// Начала строк операций; хвост строки — до начала следующей или до служебного текста.
const head = new RegExp(`(\\d{2})\\.(\\d{2})\\.(\\d{2}) ${AMT} (${OPS})(?= )`, 'g');
const STOP = /(?: ?- )?(?:Сумма заблокирована|Раздел «Краткое|АО «Kaspi Bank»|Приложение к Справке).*$/;
const marks = [...t.matchAll(head)];
const norm = (s) => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9а-яё]+/g, ' ').trim();

const ops = [];
marks.forEach((m, i) => {   // i — позиция строки в выписке (порядок как в PDF)
  const end = i + 1 < marks.length ? marks[i + 1].index : t.length;
  let tail = t.slice(m.index + m[0].length, end).replace(STOP, '');
  const orig = /\(([+-]) ?(\d{1,3}(?: \d{3})*,\d{2}) ([A-Z]{3})\)/.exec(tail);
  const fx = /Курсовая разница/.test(tail);
  const merchant = tail.replace(orig ? orig[0] : '', ' ').replace(/Курсовая разница/, ' ')
    .replace(/[^\p{L}\p{N}\p{P}\p{S} ]/gu, ' ').replace(/ {2,}/g, ' ').trim() || 'без названия';
  const amount = (m[4] === '-' ? -1 : 1) * money(m[5]);
  const kind = fx ? 'fx_diff' : (KIND[m[6]] || 'other');
  ops.push({
    card, op_date: iso(m[1], m[2], m[3]), kind, operation: m[6], merchant: merchant.slice(0, 200),
    merchant_norm: norm(merchant) || 'unknown', amount_kzt: amount,
    orig_amount: orig ? (orig[1] === '-' ? -1 : 1) * money(orig[2]) : null,
    orig_currency: orig ? orig[3] : null, pos: i,
  });
});
if (!ops.length) return fail('в выписке не нашлось ни одной операции');

// Одинаковые операции в один день (2× такси по 890 ₸) — разные траты: нумеруем по порядку.
const cnt = {};
for (const o of ops) {
  const base = `${o.card}|${o.op_date}|${o.amount_kzt.toFixed(2)}|${o.kind}|${o.merchant_norm}`;
  o.occ = cnt[base] = (cnt[base] || 0) + 1;
  o.dedup_key = `${base}|${o.occ}`;
}

const parsedBuy = ops.filter((o) => o.kind === 'purchase' || o.kind === 'fx_diff')
  .reduce((s, o) => s + o.amount_kzt, 0);
const stated = summary ? (summary[1] === '-' ? -1 : 1) * money(summary[2]) : null;
const mismatch = stated !== null && Math.abs(stated - parsedBuy) > 0.01;
return [{ json: {
  ok: true, ops, count: ops.length, card, card_label: cardLabel,
  sql_card: card.replace(/'/g, "''"), sql_card_label: cardLabel.replace(/'/g, "''"),
  period: period ? `${period[1]}.${period[2]}–${period[4]}.${period[5]}` : null,
  check: { stated, parsed: Math.round(parsedBuy * 100) / 100, mismatch },
  sql_json: JSON.stringify(ops).replace(/'/g, "''"),
} }];

// Ответ в бот: только НОВЫЕ строки (inserted; старые INSERT вернул ради позиции). В траты идут покупки
// и курсовая разница. Порядок — как в выписке (stmt_pos).
const rows = $input.all().map((i) => i.json).filter((r) => r.id && r.inserted === true)
  .sort((a, b) => Number(a.stmt_pos) - Number(b.stmt_pos));
const p = $('Parse').first().json;
const sp = (n) => Math.round(Math.abs(Number(n))).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const cur = (c) => (c === 'VND' ? '₫' : c);
const dm = (d) => String(d).slice(8, 10) + '.' + String(d).slice(5, 7);
const period = p.period ? ` ${p.period}` : '';

const buys = rows.filter((r) => r.kind === 'purchase');
const spend = rows.filter((r) => r.kind === 'purchase' || r.kind === 'fx_diff');
const other = rows.length - spend.length;
const line = (r) => {
  const refund = Number(r.amount_kzt) > 0 ? 'возврат ' : '';
  const tail = [];
  let head;
  if (r.orig_currency) { head = `${sp(r.orig_amount)} ${cur(r.orig_currency)}`; tail.push(`≈ ${sp(r.amount_kzt)} ₸`); }
  else head = `${sp(r.amount_kzt)} ₸`;
  if (r.amount_rub != null) tail.push(`≈ ${sp(r.amount_rub)} ₽`);
  return `${dm(r.op_date)} · ${refund}${head} (${tail.join(' ')}), ${r.merchant}`;
};

let text;
if (!rows.length) {
  text = `Новых операций нет — всё из выписки${period} уже записано.`;
} else {
  const kzt = -spend.reduce((s, r) => s + Number(r.amount_kzt), 0);
  const rub = -spend.reduce((s, r) => s + Number(r.amount_rub || 0), 0);
  const MAX = 40;
  const lines = buys.slice(0, MAX).map((r) => '• ' + line(r));
  if (buys.length > MAX) lines.push(`… и ещё ${buys.length - MAX}`);
  text = (buys.length ? `Записала из выписки${period} — ${buys.length} новых трат:\n` + lines.join('\n') + '\n'
                      : `Из выписки${period} новых трат нет.\n`)
    + (spend.length ? `Итого ≈ ${sp(rub)} ₽ (${sp(kzt)} ₸)${rub < 0 ? ' — в плюс' : ''}` : '')
    + (spend.length > buys.length ? '\n(с курсовой разницей)' : '')
    + (other ? `\nПереводы и пополнения: ${other} — записаны, в траты не входят.` : '');
}
if (p.check?.mismatch) text += `\n\n⚠️ Сверка не сошлась: покупки по выписке ${p.check.stated} ₸, разобрала ${p.check.parsed} ₸. Пришли выписку Claude.`;
return [{ json: { text } }];

// Разбор продавцов одним запросом к gpt-5-mini: категория, перевод названия, сеть (brand).
// GPT — основной источник категорий; словарь RULES — только запасной, если GPT не ответил
// (его подставит Classify Merge). Вход — строки «Uncategorized». Ручные категории сюда не попадают.
const rows = $input.all().map((i) => i.json).filter((r) => r.merchant_norm);
const RULES = [           // запасной словарь; порядок важен: первое совпадение побеждает
  ['fun', /cinema|cgv|karaoke|vinwonders|steam|ticket|museum|bowling|\bgame/],
  ['subs', /apple com|google|netflix|spotify|youtube|hostvds|openai|chatgpt|icloud|yandex plus|telegram/],
  ['transport', /\bgrab\b|yandex go|gojek|\bbe group|xanh sm|uber|taxi|indrive|\bbolt\b|vietjet|airasia|aviata/],
  ['health', /pharma|apteka|nha thuoc|long chau|clinic|hospital|dental|\bthuoc\b/],
  ['housing', /nha tro|apartment|arenda|\brent\b|evn|viettel|vnpt|\bfpt\b|homestay|hotel|booking/],
  ['cafe', /coffee|cafe|caphe|ca phe|highlands|starbucks|katinat|phuc long|banh mi|\bpho\b|kfc|lotteria|jollibee|mcdonald|burger|pizza|restaurant|nha hang|\bbbq|sushi|\bbar\b|\bquan\b/],
  ['shops', /winmart|co ?op|lotte mart|big c|circle k|familymart|7 eleven|ministop|bach hoa|\bmart\b|market|magazin|shop|wildberries|ozon/],
];
// fallback — категория словаря на случай, если GPT упадёт
const fallback = [];
for (const r of rows) {
  const hit = r.need_cat ? RULES.find(([, re]) => re.test(r.merchant_norm)) : null;
  if (hit) fallback.push({ merchant_norm: r.merchant_norm, category: hit[0], source: 'rule' });
}
const brands = rows[0]?.known_brands || '';
let request = null;
if (rows.length) {
  request = {
    model: 'gpt-5-mini',
    reasoning_effort: 'low',
    response_format: { type: 'json_schema', json_schema: { name: 'merchants', strict: true, schema: {
      type: 'object', additionalProperties: false, required: ['items'],
      properties: { items: { type: 'array', items: { type: 'object', additionalProperties: false,
        required: ['merchant_norm', 'category', 'ru', 'brand'],
        properties: { merchant_norm: { type: 'string' },
          category: { type: 'string', enum: ['shops', 'cafe', 'transport', 'fun', 'housing', 'subs', 'health', 'other'] },
          ru: { type: 'string' }, brand: { type: 'string' } } } } },
    } } },
    messages: [
      { role: 'system', content: 'Ты разбираешь продавцов из банковской выписки (траты во Вьетнаме и Казахстане). Для каждого верни:\n'
        + '1) category: shops — магазины и продукты, маркетплейсы; cafe — кафе, рестораны, кофейни, доставка еды; transport — такси, транспорт, билеты, топливо; fun — развлечения, кино, экскурсии, игры; housing — жильё, аренда, коммуналка, связь, отели; subs — подписки и онлайн-сервисы; health — аптеки, врачи; other — непонятно. Вьетнамские слова: quán/nhà hàng — едальня, tạp hóa — магазинчик, nhà trọ — жильё, nhà thuốc — аптека. Если по названию не понять — other.\n'
        + '2) ru — короткий перевод названия на русский, 1–4 слова, имена собственные транслитом («CUA HANG TAP HOA THANH» → «Бакалея Тхань», «NHA THUOC LONG CHAU» → «Аптека Лонг Тяу»). Если это бренд или название и так понятно (GRAB, WINMART, Apple) — пустая строка.\n'
        + '3) brand — сеть или заведение без филиала, номера, адреса и кода: как на вывеске, латиницей («WINMART+ NT 123» → «WinMart», «HIGHLANDS COFFEE 45 LE LOI» → «Highlands Coffee», «Grab» → «Grab»). Разные филиалы одной сети — одинаковый brand. Если это одиночное заведение — его название без мусора. '
        + (brands ? 'Уже известные сети (если продавец из них — пиши ровно так): ' + brands + '.\n' : '\n')
        + 'Верни каждого продавца ровно с тем merchant_norm, что дан.' },
      { role: 'user', content: rows.map((r) => `${r.merchant_norm}\t${r.merchant}`).join('\n') },
    ],
  };
}
return [{ json: { fallback, need: Object.fromEntries(rows.map((r) => [r.merchant_norm, { cat: !!r.need_cat, ru: !!r.need_ru }])),
  ask_count: rows.length, request } }];

// Сливает ответ GPT (категория, перевод, сеть) и запасной словарь. GPT важнее словаря.
// GPT не ответил — у продавцов останутся только словарные категории, а перевод/сеть не отмечены
// (name_ru_at, brand = NULL) → попадут в следующий прогон.
const prep = $('Classify Prep').first().json;
const need = prep.need || {};
const allowed = new Set(['shops', 'cafe', 'transport', 'fun', 'housing', 'subs', 'health', 'other']);
const byKey = new Map(prep.fallback.map((k) => [k.merchant_norm, { ...k, name_ru: null, brand: null, translated: false }]));
if ($json.choices) {
  try {
    const items = JSON.parse($json.choices[0].message.content).items || [];
    for (const it of items) {
      if (!it.merchant_norm || !need[it.merchant_norm]) continue;     // только то, что спрашивали
      const cur = byKey.get(it.merchant_norm) || { merchant_norm: it.merchant_norm, category: null, source: 'llm' };
      if (need[it.merchant_norm].cat && allowed.has(it.category)) { cur.category = it.category; cur.source = 'llm'; }
      if (need[it.merchant_norm].ru) {
        cur.name_ru = String(it.ru || '').trim().slice(0, 120);
        cur.brand = String(it.brand || '').trim().slice(0, 80);
        cur.translated = true;
      }
      byKey.set(it.merchant_norm, cur);
    }
  } catch (e) {}
}
const out = [...byKey.values()];
return [{ json: { count: out.length, sql_json: JSON.stringify(out).replace(/'/g, "''") } }];
